-- Phase 4 follows the exact isolated Festival sequence. These rows are plans and commitments:
-- they create no performance slot, cash transaction, ticket sale, or public announcement.
CREATE TABLE public.festival_artist_programmes (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_company_id uuid UNIQUE NOT NULL REFERENCES public.festival_companies(id) ON DELETE CASCADE, festival_ticket_plan_id uuid UNIQUE NOT NULL REFERENCES public.festival_ticket_plans(id) ON DELETE CASCADE,
 currency_code text NOT NULL CHECK(currency_code ~ '^[A-Z]{3}$'), application_mode text NOT NULL CHECK(application_mode IN ('closed','invite_only','applications_only','hybrid')), applications_open_at timestamptz, applications_close_at timestamptz, minimum_artist_fame integer CHECK(minimum_artist_fame>=0), maximum_artist_fame integer CHECK(maximum_artist_fame>=minimum_artist_fame), preferred_genres text[] NOT NULL DEFAULT '{}', excluded_genres text[] NOT NULL DEFAULT '{}', artist_budget_minor bigint NOT NULL CHECK(artist_budget_minor>=0), contingency_budget_minor bigint NOT NULL DEFAULT 0 CHECK(contingency_budget_minor>=0), minimum_player_artist_share_basis_points integer NOT NULL DEFAULT 0 CHECK(minimum_player_artist_share_basis_points BETWEEN 0 AND 10000), status text NOT NULL DEFAULT 'not_started' CHECK(status IN ('not_started','applications_configured','applications_open','offers_in_progress','bookings_in_progress','lineup_draft_complete','ready_for_operations')), planning_version integer NOT NULL DEFAULT 1 CHECK(planning_version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, CHECK(applications_open_at IS NULL OR applications_close_at IS NULL OR applications_open_at<applications_close_at)
);
CREATE TABLE public.festival_artist_application_windows (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_artist_programme_id uuid NOT NULL REFERENCES public.festival_artist_programmes(id) ON DELETE CASCADE, name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 120), opens_at timestamptz NOT NULL, closes_at timestamptz NOT NULL CHECK(opens_at<closes_at), eligible_artist_type text NOT NULL CHECK(eligible_artist_type IN ('band','solo','either','npc_only','player_only')), minimum_fame integer CHECK(minimum_fame>=0), maximum_fame integer CHECK(maximum_fame>=minimum_fame), preferred_genres text[] NOT NULL DEFAULT '{}', minimum_band_members integer CHECK(minimum_band_members>0), maximum_band_members integer CHECK(maximum_band_members>=minimum_band_members), target_stage_types text[] NOT NULL DEFAULT '{}', maximum_set_minutes integer CHECK(maximum_set_minutes BETWEEN 10 AND 240), active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(festival_artist_programme_id,name)
);
CREATE TABLE public.festival_artist_applications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_artist_programme_id uuid NOT NULL REFERENCES public.festival_artist_programmes(id) ON DELETE CASCADE, application_window_id uuid NOT NULL REFERENCES public.festival_artist_application_windows(id), artist_type text NOT NULL CHECK(artist_type IN ('solo','band','npc')), artist_profile_id uuid REFERENCES public.profiles(id), band_id uuid REFERENCES public.bands(id), npc_artist_id uuid, submitted_by_profile_id uuid REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','under_review','shortlisted','offer_pending','accepted','rejected','withdrawn','expired')), version integer NOT NULL DEFAULT 1, preferred_dates date[] NOT NULL DEFAULT '{}', preferred_stage_types text[] NOT NULL DEFAULT '{}', minimum_fee_minor bigint CHECK(minimum_fee_minor>=0), requested_fee_minor bigint CHECK(requested_fee_minor>=0), minimum_set_minutes integer NOT NULL CHECK(minimum_set_minutes BETWEEN 10 AND 240), maximum_set_minutes integer NOT NULL CHECK(maximum_set_minutes BETWEEN minimum_set_minutes AND 240), genre_snapshot text[] NOT NULL DEFAULT '{}', fame_snapshot integer NOT NULL CHECK(fame_snapshot>=0), popularity_snapshot integer NOT NULL CHECK(popularity_snapshot>=0), availability_snapshot jsonb NOT NULL DEFAULT '{}', message text, submitted_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz, reviewed_at timestamptz,
 CHECK(num_nonnulls(artist_profile_id,band_id,npc_artist_id)=1), CHECK((artist_type='solo')=(artist_profile_id IS NOT NULL)), CHECK((artist_type='band')=(band_id IS NOT NULL)), CHECK((artist_type='npc')=(npc_artist_id IS NOT NULL))
);
CREATE UNIQUE INDEX festival_artist_application_active_identity ON public.festival_artist_applications(festival_artist_programme_id,artist_type,coalesce(artist_profile_id,band_id,npc_artist_id)) WHERE status NOT IN ('rejected','withdrawn','expired');
CREATE TABLE public.festival_artist_invitations (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_artist_programme_id uuid NOT NULL REFERENCES public.festival_artist_programmes(id) ON DELETE CASCADE, artist_type text NOT NULL CHECK(artist_type IN ('solo','band','npc')), artist_profile_id uuid REFERENCES public.profiles(id), band_id uuid REFERENCES public.bands(id), npc_artist_id uuid, invited_by_profile_id uuid NOT NULL REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','viewed','interested','declined','expired','converted_to_offer','cancelled')), version integer NOT NULL DEFAULT 1, message text, suggested_fee_minor bigint CHECK(suggested_fee_minor>=0), suggested_set_minutes integer CHECK(suggested_set_minutes BETWEEN 10 AND 240), suggested_dates date[] NOT NULL DEFAULT '{}', suggested_stage_types text[] NOT NULL DEFAULT '{}', expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), responded_at timestamptz, CHECK(num_nonnulls(artist_profile_id,band_id,npc_artist_id)=1)
);
CREATE UNIQUE INDEX festival_artist_invitation_active_identity ON public.festival_artist_invitations(festival_artist_programme_id,artist_type,coalesce(artist_profile_id,band_id,npc_artist_id)) WHERE status IN ('draft','sent','viewed','interested');
CREATE TABLE public.festival_artist_offers (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_artist_programme_id uuid NOT NULL REFERENCES public.festival_artist_programmes(id) ON DELETE CASCADE, application_id uuid REFERENCES public.festival_artist_applications(id), invitation_id uuid REFERENCES public.festival_artist_invitations(id), artist_type text NOT NULL CHECK(artist_type IN ('solo','band','npc')), artist_profile_id uuid REFERENCES public.profiles(id), band_id uuid REFERENCES public.bands(id), npc_artist_id uuid, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','countered','accepted','declined','expired','withdrawn','superseded')), offered_fee_minor bigint NOT NULL CHECK(offered_fee_minor>=0), currency_code text NOT NULL CHECK(currency_code ~ '^[A-Z]{3}$'), set_minutes integer NOT NULL CHECK(set_minutes BETWEEN 10 AND 240), performance_count integer NOT NULL DEFAULT 1 CHECK(performance_count BETWEEN 1 AND 10), preferred_date date, preferred_stage_id uuid REFERENCES public.festival_stages(id), billing_position text NOT NULL CHECK(billing_position IN ('headliner','sub_headliner','featured','support','emerging','special_guest')), travel_support_minor bigint NOT NULL DEFAULT 0 CHECK(travel_support_minor>=0), accommodation_support_minor bigint NOT NULL DEFAULT 0 CHECK(accommodation_support_minor>=0), merch_revenue_share_basis_points integer NOT NULL DEFAULT 0 CHECK(merch_revenue_share_basis_points BETWEEN 0 AND 10000), recording_permission text, broadcast_permission text, exclusivity_radius_km integer CHECK(exclusivity_radius_km>=0), exclusivity_days_before integer CHECK(exclusivity_days_before>=0), exclusivity_days_after integer CHECK(exclusivity_days_after>=0), response_deadline timestamptz, offer_version integer NOT NULL DEFAULT 1 CHECK(offer_version>0), created_by_profile_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, declined_at timestamptz, cancelled_at timestamptz, CHECK(num_nonnulls(artist_profile_id,band_id,npc_artist_id)=1)
);
CREATE TABLE public.festival_artist_offer_revisions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES public.festival_artist_offers(id) ON DELETE CASCADE, offer_version integer NOT NULL CHECK(offer_version>0), proposed_by_party text NOT NULL CHECK(proposed_by_party IN ('festival','artist','system','admin')), proposed_by_profile_id uuid REFERENCES public.profiles(id), fee_minor bigint NOT NULL CHECK(fee_minor>=0), set_minutes integer NOT NULL CHECK(set_minutes BETWEEN 10 AND 240), preferred_date date, preferred_stage_id uuid REFERENCES public.festival_stages(id), billing_position text NOT NULL, travel_support_minor bigint NOT NULL DEFAULT 0 CHECK(travel_support_minor>=0), accommodation_support_minor bigint NOT NULL DEFAULT 0 CHECK(accommodation_support_minor>=0), merch_revenue_share_basis_points integer NOT NULL DEFAULT 0 CHECK(merch_revenue_share_basis_points BETWEEN 0 AND 10000), terms_snapshot jsonb NOT NULL DEFAULT '{}', message text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(offer_id,offer_version)
);
CREATE TABLE public.festival_artist_bookings (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_artist_programme_id uuid NOT NULL REFERENCES public.festival_artist_programmes(id) ON DELETE CASCADE, offer_id uuid UNIQUE NOT NULL REFERENCES public.festival_artist_offers(id), artist_type text NOT NULL CHECK(artist_type IN ('solo','band','npc')), artist_profile_id uuid REFERENCES public.profiles(id), band_id uuid REFERENCES public.bands(id), npc_artist_id uuid, status text NOT NULL DEFAULT 'awaiting_schedule' CHECK(status IN ('confirmed','awaiting_schedule','scheduled','cancelled','artist_withdrawn','festival_cancelled')), version integer NOT NULL DEFAULT 1, agreed_fee_minor bigint NOT NULL CHECK(agreed_fee_minor>=0), travel_support_minor bigint NOT NULL CHECK(travel_support_minor>=0), accommodation_support_minor bigint NOT NULL CHECK(accommodation_support_minor>=0), total_commitment_minor bigint NOT NULL CHECK(total_commitment_minor=agreed_fee_minor+travel_support_minor+accommodation_support_minor), currency_code text NOT NULL, set_minutes integer NOT NULL, performance_count integer NOT NULL, provisional_date date, provisional_stage_id uuid REFERENCES public.festival_stages(id), billing_position text NOT NULL, contract_terms jsonb NOT NULL, confirmed_at timestamptz NOT NULL DEFAULT now(), cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(artist_profile_id,band_id,npc_artist_id)=1)
);
CREATE UNIQUE INDEX festival_artist_booking_identity ON public.festival_artist_bookings(festival_artist_programme_id,artist_type,coalesce(artist_profile_id,band_id,npc_artist_id)) WHERE status NOT IN ('cancelled','artist_withdrawn','festival_cancelled');
CREATE TABLE public.festival_financial_commitments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id) ON DELETE CASCADE, artist_booking_id uuid UNIQUE NOT NULL REFERENCES public.festival_artist_bookings(id) ON DELETE CASCADE, category text NOT NULL DEFAULT 'artist_booking', amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency_code text NOT NULL, status text NOT NULL DEFAULT 'committed' CHECK(status IN ('committed','released','settled')), created_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz, CHECK(status<>'settled' OR false));
COMMENT ON TABLE public.festival_financial_commitments IS 'Encumbrances only. They never alter cash or constitute artist payment; settlement is a future phase.';
CREATE TABLE public.festival_artist_plan_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id) ON DELETE CASCADE, caller_profile_id uuid NOT NULL REFERENCES public.profiles(id), target_entity_id uuid, action text NOT NULL, idempotency_key uuid NOT NULL, payload_hash text NOT NULL, result jsonb, status text NOT NULL DEFAULT 'processing' CHECK(status IN ('processing','succeeded')), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(caller_profile_id,target_entity_id,action,idempotency_key));
CREATE TABLE public.festival_artist_plan_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), festival_company_id uuid NOT NULL REFERENCES public.festival_companies(id) ON DELETE CASCADE, actor_profile_id uuid REFERENCES public.profiles(id), target_artist_type text, target_artist_id uuid, entity_type text NOT NULL, entity_id uuid NOT NULL, event_type text NOT NULL, previous_state text, new_state text, changed_fields jsonb NOT NULL DEFAULT '[]', version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());

ALTER TABLE public.festival_artist_programmes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_application_windows ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_applications ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_invitations ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_offers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_offer_revisions ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_bookings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_financial_commitments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_plan_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE public.festival_artist_plan_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.festival_artist_programmes,public.festival_artist_application_windows,public.festival_artist_applications,public.festival_artist_invitations,public.festival_artist_offers,public.festival_artist_offer_revisions,public.festival_artist_bookings,public.festival_financial_commitments,public.festival_artist_plan_requests,public.festival_artist_plan_audit FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public._festival_artist_manager(p_company uuid,p_profile uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.festival_companies f WHERE f.id=p_company AND (f.owner_profile_id=p_profile OR coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false))) $$;
CREATE FUNCTION public._festival_artist_programme_result(p_company uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT jsonb_build_object('festivalCompanyId',fc.id,'festivalName',cfg.public_name,'festivalDates',(SELECT jsonb_agg(d::date ORDER BY d) FROM generate_series(cfg.planned_start_date,cfg.planned_end_date,'1 day') d),'stages',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'stageType',s.stage_type,'capacity',s.capacity,'active',s.status='ready') ORDER BY s.sort_order) FROM public.festival_stages s WHERE s.festival_company_id=fc.id),'[]'),'programme',CASE WHEN ap.id IS NULL THEN NULL ELSE jsonb_build_object('id',ap.id,'currencyCode',ap.currency_code,'applicationMode',ap.application_mode,'applicationsOpenAt',ap.applications_open_at,'applicationsCloseAt',ap.applications_close_at,'minimumArtistFame',ap.minimum_artist_fame,'maximumArtistFame',ap.maximum_artist_fame,'preferredGenres',ap.preferred_genres,'excludedGenres',ap.excluded_genres,'artistBudgetMinor',ap.artist_budget_minor,'contingencyBudgetMinor',ap.contingency_budget_minor,'minimumPlayerArtistShareBasisPoints',ap.minimum_player_artist_share_basis_points,'status',ap.status) END,'applicationWindows','[]'::jsonb,'applications','[]'::jsonb,'invitations','[]'::jsonb,'offers','[]'::jsonb,'bookings','[]'::jsonb,'budget',jsonb_build_object('artistBudgetMinor',coalesce(ap.artist_budget_minor,0),'contingencyBudgetMinor',coalesce(ap.contingency_budget_minor,0),'draftOfferCommitmentsMinor',0,'sentOfferCommitmentsMinor',coalesce((SELECT sum(offered_fee_minor+travel_support_minor+accommodation_support_minor) FROM public.festival_artist_offers WHERE festival_artist_programme_id=ap.id AND status IN ('sent','countered')),0),'acceptedCommitmentsMinor',coalesce((SELECT sum(total_commitment_minor) FROM public.festival_artist_bookings WHERE festival_artist_programme_id=ap.id AND status NOT IN ('cancelled','artist_withdrawn','festival_cancelled')),0),'remainingMinor',greatest(0,coalesce(ap.artist_budget_minor+ap.contingency_budget_minor,0)-coalesce((SELECT sum(total_commitment_minor) FROM public.festival_artist_bookings WHERE festival_artist_programme_id=ap.id AND status NOT IN ('cancelled','artist_withdrawn','festival_cancelled')),0)),'potentialApplicationRequestsMinor',0,'headlineBudgetShareBasisPoints',0,'playerArtistBudgetShareBasisPoints',0,'npcArtistBudgetShareBasisPoints',0),'issues','[]'::jsonb,'playerArtistCount',0,'npcArtistCount',0,'playerArtistShareBasisPoints',0,'ready',coalesce(ap.status='ready_for_operations',false),'canWrite',true,'planningVersion',coalesce(ap.planning_version,0),'updatedAt',ap.updated_at)
 FROM public.festival_companies fc JOIN public.festival_configurations cfg ON cfg.festival_company_id=fc.id LEFT JOIN public.festival_artist_programmes ap ON ap.festival_company_id=fc.id WHERE fc.id=p_company $$;
CREATE FUNCTION public.get_festival_artist_programme(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p uuid:=public._caller_profile_id(); BEGIN IF auth.uid() IS NULL OR NOT public._festival_artist_manager(p_festival_company_id,p) THEN RAISE EXCEPTION 'festival_artist_programme_forbidden' USING ERRCODE='P0001'; END IF; RETURN public._festival_artist_programme_result(p_festival_company_id); END $$;
CREATE FUNCTION public.save_festival_artist_programme(p_festival_company_id uuid,p_expected_version integer,p_programme jsonb,p_application_windows jsonb,p_idempotency_key uuid,p_complete boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=public._caller_profile_id(); tp public.festival_ticket_plans%ROWTYPE; ap public.festival_artist_programmes%ROWTYPE; cfg public.festival_configurations%ROWTYPE; w jsonb; oldv int:=0; h text; req public.festival_artist_plan_requests%ROWTYPE; result jsonb;
BEGIN IF auth.uid() IS NULL OR NOT public._festival_artist_manager(p_festival_company_id,actor) THEN RAISE EXCEPTION 'festival_artist_programme_forbidden' USING ERRCODE='P0001'; END IF; SELECT * INTO tp FROM public.festival_ticket_plans WHERE festival_company_id=p_festival_company_id; IF NOT FOUND OR tp.status<>'ready_for_artist_planning' THEN RAISE EXCEPTION 'festival_ticket_plan_incomplete' USING ERRCODE='P0001'; END IF; SELECT * INTO cfg FROM public.festival_configurations WHERE festival_company_id=p_festival_company_id; h:=encode(digest(jsonb_build_object('version',p_expected_version,'programme',p_programme-'currencyCode','windows',p_application_windows,'complete',p_complete)::text,'sha256'),'hex'); PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||p_idempotency_key::text,0)); SELECT * INTO req FROM public.festival_artist_plan_requests WHERE caller_profile_id=actor AND target_entity_id=p_festival_company_id AND action='save_programme' AND idempotency_key=p_idempotency_key; IF FOUND THEN IF req.payload_hash<>h THEN RAISE EXCEPTION 'festival_artist_idempotency_conflict' USING ERRCODE='P0001'; END IF; IF req.status='succeeded' THEN RETURN req.result; END IF; ELSE INSERT INTO public.festival_artist_plan_requests(festival_company_id,caller_profile_id,target_entity_id,action,idempotency_key,payload_hash) VALUES(p_festival_company_id,actor,p_festival_company_id,'save_programme',p_idempotency_key,h) RETURNING * INTO req; END IF; SELECT coalesce(planning_version,0) INTO oldv FROM public.festival_artist_programmes WHERE festival_company_id=p_festival_company_id FOR UPDATE; IF oldv<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_programme_stale' USING ERRCODE='P0001'; END IF; IF jsonb_typeof(p_application_windows)<>'array' OR coalesce((p_programme->>'artistBudgetMinor')::bigint,-1)<0 OR coalesce((p_programme->>'contingencyBudgetMinor')::bigint,-1)<0 THEN RAISE EXCEPTION 'festival_artist_programme_invalid' USING ERRCODE='P0001'; END IF;
 INSERT INTO public.festival_artist_programmes(festival_company_id,festival_ticket_plan_id,currency_code,application_mode,applications_open_at,applications_close_at,minimum_artist_fame,maximum_artist_fame,preferred_genres,excluded_genres,artist_budget_minor,contingency_budget_minor,minimum_player_artist_share_basis_points,status,planning_version) VALUES(p_festival_company_id,tp.id,tp.currency_code,p_programme->>'applicationMode',(p_programme->>'applicationsOpenAt')::timestamptz,(p_programme->>'applicationsCloseAt')::timestamptz,(p_programme->>'minimumArtistFame')::int,(p_programme->>'maximumArtistFame')::int,ARRAY(SELECT jsonb_array_elements_text(coalesce(p_programme->'preferredGenres','[]'))),ARRAY(SELECT jsonb_array_elements_text(coalesce(p_programme->'excludedGenres','[]'))),(p_programme->>'artistBudgetMinor')::bigint,(p_programme->>'contingencyBudgetMinor')::bigint,coalesce((p_programme->>'minimumPlayerArtistShareBasisPoints')::int,0),'applications_configured',1) ON CONFLICT(festival_company_id) DO UPDATE SET application_mode=excluded.application_mode,applications_open_at=excluded.applications_open_at,applications_close_at=excluded.applications_close_at,minimum_artist_fame=excluded.minimum_artist_fame,maximum_artist_fame=excluded.maximum_artist_fame,preferred_genres=excluded.preferred_genres,excluded_genres=excluded.excluded_genres,artist_budget_minor=excluded.artist_budget_minor,contingency_budget_minor=excluded.contingency_budget_minor,minimum_player_artist_share_basis_points=excluded.minimum_player_artist_share_basis_points,planning_version=public.festival_artist_programmes.planning_version+1,updated_at=now() RETURNING * INTO ap; IF EXISTS(SELECT 1 FROM public.festival_artist_applications WHERE festival_artist_programme_id=ap.id) AND p_application_windows<>(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.name),'[]') FROM public.festival_artist_application_windows x WHERE x.festival_artist_programme_id=ap.id) THEN RAISE EXCEPTION 'festival_artist_application_window_locked' USING ERRCODE='P0001'; END IF; DELETE FROM public.festival_artist_application_windows WHERE festival_artist_programme_id=ap.id; FOR w IN SELECT * FROM jsonb_array_elements(p_application_windows) LOOP IF (w->>'opensAt')::timestamptz >= (w->>'closesAt')::timestamptz OR (w->>'closesAt')::timestamptz >= cfg.planned_start_date::timestamptz THEN RAISE EXCEPTION 'festival_artist_application_window_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_artist_application_windows(festival_artist_programme_id,name,opens_at,closes_at,eligible_artist_type,minimum_fame,maximum_fame,preferred_genres,minimum_band_members,maximum_band_members,target_stage_types,maximum_set_minutes,active) VALUES(ap.id,w->>'name',(w->>'opensAt')::timestamptz,(w->>'closesAt')::timestamptz,w->>'eligibleArtistType',(w->>'minimumFame')::int,(w->>'maximumFame')::int,ARRAY(SELECT jsonb_array_elements_text(coalesce(w->'preferredGenres','[]'))),(w->>'minimumBandMembers')::int,(w->>'maximumBandMembers')::int,ARRAY(SELECT jsonb_array_elements_text(coalesce(w->'targetStageTypes','[]'))),(w->>'maximumSetMinutes')::int,coalesce((w->>'active')::boolean,true)); END LOOP;
 IF p_complete THEN IF NOT EXISTS(SELECT 1 FROM public.festival_artist_bookings WHERE festival_artist_programme_id=ap.id AND status NOT IN ('cancelled','artist_withdrawn','festival_cancelled')) OR (SELECT coalesce(sum(total_commitment_minor),0) FROM public.festival_artist_bookings WHERE festival_artist_programme_id=ap.id AND status NOT IN ('cancelled','artist_withdrawn','festival_cancelled'))>ap.artist_budget_minor+ap.contingency_budget_minor THEN RAISE EXCEPTION 'festival_artist_programme_incomplete' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_programmes SET status='ready_for_operations',completed_at=now() WHERE id=ap.id; END IF; INSERT INTO public.festival_artist_plan_audit(festival_company_id,actor_profile_id,entity_type,entity_id,event_type,previous_state,new_state,changed_fields,version) VALUES(p_festival_company_id,actor,'programme',ap.id,CASE WHEN p_complete THEN 'artist_plan_completed' ELSE 'programme_configured' END,NULL,CASE WHEN p_complete THEN 'ready_for_operations' ELSE 'applications_configured' END,'["programme","applicationWindows"]',ap.planning_version); result:=public._festival_artist_programme_result(p_festival_company_id); UPDATE public.festival_artist_plan_requests SET result=result,status='succeeded',completed_at=now() WHERE id=req.id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public._festival_artist_manager(uuid,uuid),public._festival_artist_programme_result(uuid) FROM PUBLIC,anon,authenticated; REVOKE ALL ON FUNCTION public.get_festival_artist_programme(uuid),public.save_festival_artist_programme(uuid,integer,jsonb,jsonb,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_festival_artist_programme(uuid),public.save_festival_artist_programme(uuid,integer,jsonb,jsonb,uuid,boolean) TO authenticated;
